<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import type { FormInstance, FormRules } from 'element-plus'
import { ElMessage } from 'element-plus'
import { Operation, Plus, Refresh, Search } from '@element-plus/icons-vue'
import { api, apiErrorMessage, apiFieldErrors, ensureCsrf } from '../services/api'
import { authStore } from '../stores/auth'
import type { Company, ExecutionStrategy, JobPosition, MockExecutionOutcome, RecruitmentTask, RecruitmentTaskStatus, TaskExecution } from '../types'

interface TaskForm { jobPositionId: string; bossAccountId: string; name: string; executionStrategy: ExecutionStrategy; dailyQuota: number; windowStart: string; windowEnd: string; timezone: string; requireManualReview: boolean; mockOutcome: MockExecutionOutcome }
const loading=ref(true), loadError=ref(''), tasks=ref<RecruitmentTask[]>([]), jobs=ref<JobPosition[]>([]), companies=ref<Company[]>([])
const keyword=ref(''), companyFilter=ref(''), statusFilter=ref<RecruitmentTaskStatus|''>('')
const dialogOpen=ref(false), saving=ref(false), editing=ref<RecruitmentTask|null>(null), formRef=ref<FormInstance>(), formError=ref('')
const form=reactive<TaskForm>({jobPositionId:'',bossAccountId:'',name:'',executionStrategy:'BALANCED',dailyQuota:10,windowStart:'00:00',windowEnd:'23:59',timezone:'Asia/Shanghai',requireManualReview:true,mockOutcome:'SUCCESS'})
const fieldErrors=reactive<Record<string,string>>({}), actingId=ref(''), executionsOpen=ref(false), executions=ref<TaskExecution[]>([]), executionTask=ref<RecruitmentTask|null>(null), executionsLoading=ref(false)
const canManage=computed(()=>['SYSTEM_ADMIN','RECRUITMENT_ADMIN'].includes(authStore.state.user?.role??''))
const activeJobs=computed(()=>jobs.value.filter(j=>j.status==='ACTIVE'))
const selectedJob=computed(()=>jobs.value.find(j=>j.id===form.jobPositionId))
const stats=computed(()=>({total:tasks.value.length,running:tasks.value.filter(t=>t.status==='RUNNING').length,attention:tasks.value.filter(t=>['FAILED','NEEDS_ATTENTION'].includes(t.status)).length}))
const statusLabels:Record<RecruitmentTaskStatus,string>={DRAFT:'草稿',READY:'待启动',RUNNING:'运行中',PAUSED:'已暂停',COMPLETED:'已完成',FAILED:'失败',NEEDS_ATTENTION:'需人工介入'}
const strategyLabels:Record<ExecutionStrategy,string>={BALANCED:'均衡',QUALITY_FIRST:'质量优先',FAST:'效率优先'}
const outcomeLabels:Record<MockExecutionOutcome,string>={SUCCESS:'成功',FAILURE:'失败',NEEDS_ATTENTION:'需人工介入'}
const rules:FormRules<TaskForm>={jobPositionId:[{required:true,message:'请选择已启用职位',trigger:'change'}],name:[{required:true,message:'请输入任务名称',trigger:'blur'}],windowStart:[{required:true,pattern:/^([01]\d|2[0-3]):[0-5]\d$/,message:'请使用 HH:mm 格式',trigger:'blur'}],windowEnd:[{required:true,pattern:/^([01]\d|2[0-3]):[0-5]\d$/,message:'请使用 HH:mm 格式',trigger:'blur'}],timezone:[{required:true,message:'请输入 IANA 时区',trigger:'blur'}]}

function tagType(s:RecruitmentTaskStatus){return ({DRAFT:'info',READY:'warning',RUNNING:'success',PAUSED:'warning',COMPLETED:'success',FAILED:'danger',NEEDS_ATTENTION:'danger'} as const)[s]}
function clearErrors(){Object.keys(fieldErrors).forEach(k=>delete fieldErrors[k])}
async function loadData(){loading.value=true;loadError.value='';try{const [tr,jr,cr]=await Promise.all([api.get<RecruitmentTask[]>('/recruitment-tasks',{params:{keyword:keyword.value.trim()||undefined,companyId:companyFilter.value||undefined,status:statusFilter.value||undefined}}),api.get<JobPosition[]>('/job-positions'),api.get<Company[]>('/organization/companies')]);tasks.value=tr.data;jobs.value=jr.data;companies.value=cr.data}catch(e){loadError.value=apiErrorMessage(e,'招聘任务加载失败')}finally{loading.value=false}}
function chooseJob(){form.bossAccountId=selectedJob.value?.bossAccount.id??''}
function openCreate(){editing.value=null;Object.assign(form,{jobPositionId:activeJobs.value[0]?.id??'',bossAccountId:activeJobs.value[0]?.bossAccount.id??'',name:'',executionStrategy:'BALANCED',dailyQuota:10,windowStart:'00:00',windowEnd:'23:59',timezone:'Asia/Shanghai',requireManualReview:true,mockOutcome:'SUCCESS'});formError.value='';clearErrors();dialogOpen.value=true}
function openEdit(t:RecruitmentTask){editing.value=t;Object.assign(form,{jobPositionId:t.jobPosition.id,bossAccountId:t.bossAccount.id,name:t.name,executionStrategy:t.executionStrategy,dailyQuota:t.dailyQuota,windowStart:t.windowStart.slice(0,5),windowEnd:t.windowEnd.slice(0,5),timezone:t.timezone,requireManualReview:t.requireManualReview,mockOutcome:t.mockOutcome});formError.value='';clearErrors();dialogOpen.value=true}
async function save(){formError.value='';clearErrors();if(!(await formRef.value?.validate().catch(()=>false)))return;saving.value=true;try{await ensureCsrf();editing.value?await api.put(`/recruitment-tasks/${editing.value.id}`,form):await api.post('/recruitment-tasks',form);ElMessage.success(editing.value?'任务已更新':'任务草稿已创建');dialogOpen.value=false;await loadData()}catch(e){Object.assign(fieldErrors,apiFieldErrors(e));formError.value=apiErrorMessage(e,'任务保存失败')}finally{saving.value=false}}
async function changeStatus(t:RecruitmentTask,status:RecruitmentTaskStatus){actingId.value=t.id;try{await ensureCsrf();await api.patch(`/recruitment-tasks/${t.id}/status`,{status});ElMessage.success(`任务已变更为${statusLabels[status]}`);await loadData()}catch(e){ElMessage.error(apiErrorMessage(e,'任务状态变更失败'))}finally{actingId.value=''}}
async function execute(t:RecruitmentTask,retry=false){actingId.value=t.id;try{await ensureCsrf();const key=`ui-${t.id}-${Date.now()}-${crypto.randomUUID()}`;const {data}=await api.post(`/recruitment-tasks/${t.id}/${retry?'retry':'run'}`,null,{headers:{'Idempotency-Key':key}});ElMessage.success(`Mock 执行${data.execution.status==='SUCCEEDED'?'成功':'已记录'}，处理 ${data.execution.processedCount} 项`);await loadData()}catch(e){ElMessage.error(apiErrorMessage(e,'任务执行失败'))}finally{actingId.value=''}}
async function showExecutions(t:RecruitmentTask){executionTask.value=t;executionsOpen.value=true;executionsLoading.value=true;try{executions.value=(await api.get<TaskExecution[]>(`/recruitment-tasks/${t.id}/executions`)).data}catch(e){ElMessage.error(apiErrorMessage(e,'执行记录加载失败'))}finally{executionsLoading.value=false}}
function formatDate(v?:string){return v?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'尚未执行'}
onMounted(loadData)
</script>

<template><div class="page-shell"><header class="page-heading"><div><h1>自动招聘任务</h1><p>编排职位、BOSS 账号、配额和执行窗口，并对每次 Gateway 执行留痕。</p></div><el-button v-if="canManage" type="primary" :icon="Plus" @click="openCreate">新增任务</el-button></header><el-alert title="当前仅执行 Mock Gateway；每次运行使用幂等键，并受每日配额、时区和运行窗口约束。" type="info" :closable="false" show-icon class="scope-alert"/><div v-if="loading" class="surface-panel skeleton-stack"><el-skeleton :rows="7" animated/></div><div v-else-if="loadError" class="surface-panel error-state"><el-icon><Refresh/></el-icon><strong>任务暂时无法加载</strong><span>{{loadError}}</span><el-button @click="loadData">重新加载</el-button></div><template v-else><div class="metrics-strip"><div><span>任务总数</span><strong>{{stats.total}}</strong></div><div><span>运行中</span><strong>{{stats.running}}</strong></div><div><span>需关注</span><strong>{{stats.attention}}</strong></div></div><section class="surface-panel tasks-panel"><div class="section-title-row tasks-title"><div><h2>任务列表</h2><p>通过状态机控制启动、暂停、恢复和失败重试</p></div><div class="filters"><el-input v-model="keyword" clearable placeholder="搜索任务、职位或 BOSS 账号" :prefix-icon="Search" @keyup.enter="loadData"/><el-select v-model="companyFilter" clearable placeholder="全部企业" @change="loadData"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="statusFilter" placeholder="全部状态" @change="loadData"><el-option label="全部状态" value=""/><el-option v-for="(label,value) in statusLabels" :key="value" :label="label" :value="value"/></el-select><el-button @click="loadData">查询</el-button></div></div><div v-if="!tasks.length" class="empty-state"><el-icon><Operation/></el-icon><strong>还没有符合条件的招聘任务</strong><span>需要先准备已启用职位和可用 BOSS Capability。</span><el-button v-if="canManage" type="primary" @click="openCreate">新增任务</el-button></div><template v-else><el-table :data="tasks" class="tasks-table"><el-table-column label="任务" min-width="190"><template #default="{row}"><strong>{{row.name}}</strong><div class="muted">{{strategyLabels[row.executionStrategy as ExecutionStrategy]}}·{{row.requireManualReview?'人工审核':'自动审核'}}</div></template></el-table-column><el-table-column label="职位 / 企业" min-width="210"><template #default="{row}"><strong>{{row.jobPosition.title}}</strong><div class="muted">{{row.jobPosition.companyName}}</div></template></el-table-column><el-table-column label="BOSS 账号" min-width="150"><template #default="{row}">{{row.bossAccount.displayName}}</template></el-table-column><el-table-column label="当日进度" width="130"><template #default="{row}">{{row.processedToday}} / {{row.dailyQuota}}<div class="muted">{{row.windowStart.slice(0,5)}}-{{row.windowEnd.slice(0,5)}}</div></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="tagType(row.status)">{{statusLabels[row.status as RecruitmentTaskStatus]}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="270" fixed="right"><template #default="{row}"><el-button link @click="showExecutions(row as RecruitmentTask)">记录</el-button><template v-if="canManage"><el-button v-if="['DRAFT','PAUSED','FAILED','NEEDS_ATTENTION'].includes(row.status)" link type="primary" @click="openEdit(row as RecruitmentTask)">编辑</el-button><el-button v-if="row.status==='DRAFT'" link type="primary" @click="changeStatus(row as RecruitmentTask,'READY')">就绪</el-button><el-button v-if="row.status==='READY'" link type="success" @click="changeStatus(row as RecruitmentTask,'RUNNING')">启动</el-button><el-button v-if="row.status==='RUNNING'" link type="primary" :loading="actingId===row.id" @click="execute(row as RecruitmentTask)">执行一轮</el-button><el-button v-if="row.status==='RUNNING'" link type="warning" @click="changeStatus(row as RecruitmentTask,'PAUSED')">暂停</el-button><el-button v-if="row.status==='PAUSED'" link type="success" @click="changeStatus(row as RecruitmentTask,'RUNNING')">恢复</el-button><el-button v-if="['FAILED','NEEDS_ATTENTION'].includes(row.status)" link type="danger" :loading="actingId===row.id" @click="execute(row as RecruitmentTask,true)">重试</el-button></template></template></el-table-column></el-table><div class="task-cards"><article v-for="t in tasks" :key="t.id"><header><div><strong>{{t.name}}</strong><span>{{t.jobPosition.title}}</span></div><el-tag :type="tagType(t.status)" size="small">{{statusLabels[t.status]}}</el-tag></header><dl><div><dt>企业</dt><dd>{{t.jobPosition.companyName}}</dd></div><div><dt>BOSS</dt><dd>{{t.bossAccount.displayName}}</dd></div><div><dt>配额</dt><dd>{{t.processedToday}} / {{t.dailyQuota}}</dd></div><div><dt>窗口</dt><dd>{{t.windowStart.slice(0,5)}}-{{t.windowEnd.slice(0,5)}}</dd></div></dl><p v-if="t.lastError" class="task-error">{{t.lastError}}</p><footer><el-button @click="showExecutions(t)">记录</el-button><template v-if="canManage"><el-button v-if="['DRAFT','PAUSED','FAILED','NEEDS_ATTENTION'].includes(t.status)" @click="openEdit(t)">编辑</el-button><el-button v-if="t.status==='DRAFT'" type="primary" plain @click="changeStatus(t,'READY')">就绪</el-button><el-button v-if="t.status==='READY'" type="success" plain @click="changeStatus(t,'RUNNING')">启动</el-button><el-button v-if="t.status==='RUNNING'" type="primary" plain @click="execute(t)">执行一轮</el-button><el-button v-if="t.status==='RUNNING'" type="warning" plain @click="changeStatus(t,'PAUSED')">暂停</el-button><el-button v-if="t.status==='PAUSED'" type="success" plain @click="changeStatus(t,'RUNNING')">恢复</el-button><el-button v-if="['FAILED','NEEDS_ATTENTION'].includes(t.status)" type="danger" plain @click="execute(t,true)">重试</el-button></template></footer></article></div></template></section></template>
<el-dialog v-model="dialogOpen" :title="editing?'编辑招聘任务':'新增招聘任务'" width="720px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="form-grid"><el-form-item label="已启用职位" prop="jobPositionId" :error="fieldErrors.jobPositionId"><el-select v-model="form.jobPositionId" filterable :disabled="!!editing" @change="chooseJob"><el-option v-for="j in activeJobs" :key="j.id" :label="`${j.title}（${j.company.name}）`" :value="j.id"/></el-select></el-form-item><el-form-item label="BOSS 账号"><el-input :model-value="selectedJob?.bossAccount.displayName??''" disabled/></el-form-item><el-form-item label="任务名称" prop="name"><el-input v-model="form.name" maxlength="120"/></el-form-item><el-form-item label="执行策略"><el-select v-model="form.executionStrategy"><el-option v-for="(label,value) in strategyLabels" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="每日配额"><el-input-number v-model="form.dailyQuota" :min="1" :max="500"/></el-form-item><el-form-item label="Mock 执行结果"><el-select v-model="form.mockOutcome"><el-option v-for="(label,value) in outcomeLabels" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="开始时间" prop="windowStart"><el-input v-model="form.windowStart" placeholder="00:00"/></el-form-item><el-form-item label="结束时间" prop="windowEnd"><el-input v-model="form.windowEnd" placeholder="23:59"/></el-form-item><el-form-item label="IANA 时区" prop="timezone"><el-input v-model="form.timezone"/></el-form-item><el-form-item label="发送前人工审核"><el-switch v-model="form.requireManualReview" inline-prompt active-text="是" inactive-text="否"/></el-form-item></div></el-form><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{editing?'保存修改':'创建草稿'}}</el-button></template></el-dialog>
<el-drawer v-model="executionsOpen" :title="`${executionTask?.name??''} · 执行记录`" size="min(560px, 92vw)"><el-skeleton v-if="executionsLoading" :rows="6" animated/><el-empty v-else-if="!executions.length" description="尚无执行记录"/><div v-else class="execution-list"><article v-for="e in executions" :key="e.id"><header><strong>第 {{e.attemptNumber}} 次执行</strong><el-tag :type="e.status==='SUCCEEDED'?'success':'danger'">{{e.status==='SUCCEEDED'?'成功':e.status==='FAILED'?'失败':'需人工介入'}}</el-tag></header><p>{{e.message}}</p><footer><span>处理 {{e.processedCount}} / 请求 {{e.requestedCount}}</span><time>{{formatDate(e.startedAt)}}</time></footer></article></div></el-drawer></div></template>
<style scoped>.scope-alert{margin-bottom:20px}.metrics-strip{display:grid;grid-template-columns:repeat(3,1fr);margin-bottom:20px;border:1px solid var(--border);border-radius:12px;background:var(--surface);overflow:hidden}.metrics-strip div{padding:18px 24px;border-right:1px solid var(--border)}.metrics-strip div:last-child{border:0}.metrics-strip span,.metrics-strip strong{display:block}.metrics-strip span,.muted{color:var(--text-secondary);font-size:12px}.metrics-strip strong{margin-top:5px;font-size:24px}.tasks-panel{overflow:hidden}.tasks-title{align-items:flex-end}.filters{display:grid;grid-template-columns:minmax(220px,280px) 150px 140px auto;gap:8px}.tasks-table{width:100%}.task-cards{display:none}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.form-grid .el-select,.form-grid .el-input-number{width:100%}.execution-list{display:grid;gap:12px}.execution-list article{padding:16px;border:1px solid var(--border);border-radius:10px}.execution-list header,.execution-list footer{display:flex;justify-content:space-between;gap:12px}.execution-list p{color:var(--text-secondary)}.execution-list footer{font-size:12px;color:var(--text-secondary)}
@media(max-width:1250px){.tasks-title{display:grid}.filters{width:100%;grid-template-columns:minmax(200px,1fr) 145px 135px auto}}
@media(max-width:720px){.metrics-strip div{padding:14px 12px}.filters{grid-template-columns:1fr}.tasks-table{display:none}.task-cards{display:grid;gap:12px;padding:14px}.task-cards article{padding:16px;border:1px solid var(--border);border-radius:10px}.task-cards header{display:flex;justify-content:space-between;gap:12px}.task-cards header span{display:block;margin-top:5px;color:var(--text-secondary);font-size:12px}.task-cards dl{display:grid;gap:10px;margin:16px 0}.task-cards dl div{display:grid;grid-template-columns:65px 1fr}.task-cards dt{color:var(--text-secondary)}.task-cards dd{margin:0}.task-error{color:var(--danger);font-size:13px}.task-cards footer{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.task-cards footer .el-button{margin:0;min-height:42px}.form-grid{grid-template-columns:1fr}}</style>
